from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent.parent
scenes=json.loads((ROOT/'scenes.json').read_text())
options=''.join(f'<option value="{s["id"]}">{s["id"][:2]} · {s["title"]}</option>' for s in scenes)
cards=''.join(f'<a class="chapter" href="images/{s["id"]}-mobile.png"><img src="images/{s["id"]}-mobile.png" loading="lazy" alt="{s["title"]} mobile"><strong>{s["id"][:2]} · {s["title"]}</strong></a>' for s in scenes)
style='''*{box-sizing:border-box}body{margin:0;background:#fff9ee;color:#29251d;font:15px/1.6 Arial,sans-serif}a{color:#1d5c54}header,main,footer{max-width:1440px;margin:auto;padding:28px}h1{font-size:40px;letter-spacing:-.05em;line-height:1.1;margin:12px 0}p{color:#655a43}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:13px}.tools{display:flex;flex-wrap:wrap;gap:15px;padding:20px;background:#f3e6c8;border-radius:10px;margin:25px 0}select,button{font:inherit;padding:11px;border:1px solid #7a6a4d;border-radius:7px;background:white;color:#29251d;min-height:44px}button{cursor:pointer}button[aria-pressed=true]{background:#1d5c54;color:white}.viewer{background:#e9e3d7;border:1px solid #b7ab93;padding:25px;text-align:center;overflow:auto;max-height:900px}.viewer img{display:block;margin:auto;max-width:100%;height:auto}.viewer.mobile img{max-width:390px}.viewer.tablet img{max-width:834px}.label{display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}.chapters{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:20px}.chapter{text-decoration:none;background:#f3e6c8;border-radius:10px;padding:15px;overflow:hidden}.chapter img{height:260px;width:100%;object-fit:cover;object-position:top;display:block;margin-bottom:14px}.chapter strong{font-size:12px}.notice{padding:18px;background:#dde7d7;border-radius:10px;font-size:13px}iframe{width:100%;height:900px;border:1px solid #7a6a4d}a:focus-visible,button:focus-visible,select:focus-visible{outline:2px solid #005fcc;outline-offset:4px}.routes{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.routes a{background:#f3e6c8;border-radius:10px;padding:20px;text-decoration:none}.routes p{font-size:12px}@media(max-width:800px){.chapters,.routes{grid-template-columns:repeat(2,1fr)}header,main,footer{padding:20px}.tools{padding:15px}h1{font-size:34px}.viewer{padding:10px}.tools select{max-width:100%}}'''
gallery=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playfield · 45 responsive design mockups</title><style>{style}</style></head><body><header><p>LETBUYY / BLOOM / PLAYFIELD V1 · 22 OCTOBER 2026</p><h1>A curious day, thoughtfully chosen.</h1><p>15 connected scenes · 45 independently rendered PNGs · 15 extra comparison boards.</p><nav><a href="Playfield-45-mockups.zip">Download 45 PNGs</a><a href="prototype-index.html">Editable source routes</a><a href="comparisons/index.html">Shopify references & neutral structures</a><a href="README.md">Design handoff</a><a href="validation.json">Artifact validation</a></nav></header><main><div class="notice">Visual references, fictional catalog and buyer data. These are design artifacts. Production wiring, payment, identity and publication are not demonstrated by this gallery.</div><div class="tools"><label>Scene <select id="scene">{options}</select></label><div id="devices"><button data-device="desktop" aria-pressed="true">Desktop</button> <button data-device="tablet" aria-pressed="false">Tablet</button> <button data-device="mobile" aria-pressed="false">Mobile</button> <button data-device="board" aria-pressed="false">All three</button></div></div><div class="label"><p id="caption">01 · Home · choose a curious day</p><a id="full" href="images/01-home-top-desktop.png">Open full-resolution PNG</a></div><div class="viewer" id="viewer"><img id="screen" src="images/01-home-top-desktop.png" alt="Playfield home desktop"></div><h2>All fifteen chapters</h2><p>Mobile previews below link to their full PNGs. Use the selector above for each independently rendered device.</p><div class="chapters">{cards}</div></main><footer>Playfield design pack · Versioned Bloom transition proposal · No production changes</footer><script>const data={json.dumps(scenes)};let device='desktop';const sel=document.getElementById('scene');function update(){{const s=data.find(x=>x.id===sel.value);const f=device==='board'?'boards/'+s.id+'.png':'images/'+s.id+'-'+device+'.png';document.getElementById('screen').src=f;document.getElementById('screen').alt=s.title+' '+device;document.getElementById('full').href=f;document.getElementById('caption').textContent=s.id.slice(0,2)+' · '+s.title+' · '+device;document.getElementById('viewer').className='viewer '+device;document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.device===device));}}sel.onchange=update;document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{{device=b.dataset.device;update();}});</script></body></html>'''
(ROOT/'index.html').write_text(gallery)
routes=''.join(f'<a href="{s["source"]}"><strong>{s["id"][:2]} · {s["title"]}</strong><p>{html.escape(s["description"])}</p><p>{html.escape(s["intendedRoute"])}</p></a>' for s in scenes)
(ROOT/'prototype-index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Playfield · editable visual source</title><style>{style}</style></head><body><header><nav><a href="index.html">Screenshot storybook</a><a href="README.md">Handoff</a></nav><h1>Explore the responsive source.</h1><p>One CSS presentation system. Scene 01 + 02 are one homepage; 04 + 05 + 06 are one PDP. Repeated context is for standalone story images, not extra production routes.</p><p class="notice">Local presentation only. Age/interest controls demonstrate fixture composition; other commerce controls are visual proposals requiring their canonical service. No form submits credentials or payment.</p></header><main><div class="routes">{routes}</div></main></body></html>')
print('Gallery and prototype index written')
